import hashlib
import hmac
import json
import time
import os
from dataclasses import dataclass, field
from typing import Any, Dict, Optional, Tuple

# IoT Firmware Role-Based Access Control System
# Supports: admin, operator, viewer roles

SECRET_KEY = os.urandom(32)
SESSION_STORE: Dict[str, dict] = {}

@dataclass
class DeviceConfig:
    firmware_version: str = "2.4.1"
    max_sessions: int = 16
    session_timeout: int = 3600
    role_hierarchy: Dict[str, int] = field(default_factory=lambda: {
        "admin": 100,
        "operator": 50,
        "viewer": 10
    })

config = DeviceConfig()

def create_session_token(user_id: str, role: str) -> str:
    """Create HMAC-signed session token."""
    if role not in config.role_hierarchy:
        raise ValueError(f"Invalid role: {role}")
    timestamp = int(time.time())
    payload = f"{user_id}:{role}:{timestamp}"
    signature = hmac.new(SECRET_KEY, payload.encode(), hashlib.sha256).hexdigest()
    token = f"{payload}:{signature}"
    SESSION_STORE[token] = {
        "user_id": user_id,
        "role": role,
        "created": timestamp,
        "permissions": _resolve_permissions(role)
    }
    return token

def _resolve_permissions(role: str) -> dict:
    """Resolve effective permissions for a role."""
    base_perms = {
        "read_sensors": True,
        "write_config": False,
        "firmware_update": False,
        "manage_users": False,
        "factory_reset": False
    }
    if role == "operator":
        base_perms["write_config"] = True
    elif role == "admin":
        base_perms["write_config"] = True
        base_perms["firmware_update"] = True
        base_perms["manage_users"] = True
        base_perms["factory_reset"] = True
    return base_perms

def validate_session(token: str) -> Optional[dict]:
    """Validate session token and return session data."""
    if token not in SESSION_STORE:
        return None
    session = SESSION_STORE[token]
    if int(time.time()) - session["created"] > config.session_timeout:
        del SESSION_STORE[token]
        return None
    return session

def check_permission(session: dict, required_permission: str) -> bool:
    """Check if session has the required permission."""
    permissions = session.get("permissions", {})
    return permissions.get(required_permission, False)

def get_role_level(role_value: str) -> int:
    """Get numeric level for a role string."""
    if not isinstance(role_value, str):
        raise TypeError(f"Role must be a string, got {type(role_value).__name__}")
    return config.role_hierarchy.get(role_value, 0)

def authorize_action(session: dict, action: str, min_role: str = "operator") -> Tuple[bool, str]:
    """Authorize an action based on role hierarchy.

    Args:
        session: validated session dict
        action: action identifier string
        min_role: minimum role required (must be a valid role string)

    Returns:
        Tuple of (authorized: bool, reason: str)
    """
    if not isinstance(min_role, str):
        raise TypeError(f"min_role must be a string, got {type(min_role).__name__}")

    user_role = session.get("role", "viewer")
    if not isinstance(user_role, str):
        return (False, "Invalid session role type")

    user_level = get_role_level(user_role)
    required_level = get_role_level(min_role)

    if user_level >= required_level:
        return (True, "authorized")
    return (False, f"Insufficient role level: {user_level} < {required_level}")

def handle_api_request(token: str, endpoint: str, payload: dict) -> dict:
    """Main API request handler for the IoT device."""
    session = validate_session(token)
    if session is None:
        return {"error": "Invalid or expired session", "code": 401}

    if endpoint == "/sensors/read":
        authorized, reason = authorize_action(session, "read_sensors", "viewer")
        if not authorized:
            return {"error": reason, "code": 403}
        return {"data": {"temperature": 22.5, "humidity": 45.2}, "code": 200}

    elif endpoint == "/config/update":
        authorized, reason = authorize_action(session, "write_config", "operator")
        if not authorized:
            return {"error": reason, "code": 403}
        return {"data": "config updated", "code": 200}

    elif endpoint == "/firmware/update":
        authorized, reason = authorize_action(session, "firmware_update", "admin")
        if not authorized:
            return {"error": reason, "code": 403}
        return {"data": "firmware update initiated", "code": 200}

    elif endpoint == "/admin/factory_reset":
        # Critical action: requires admin AND explicit permission check
        authorized, reason = authorize_action(session, "factory_reset", "admin")
        if not authorized:
            return {"error": reason, "code": 403}
        if not check_permission(session, "factory_reset"):
            return {"error": "Permission denied", "code": 403}
        return {"data": "factory reset scheduled", "code": 200}

    elif endpoint == "/admin/elevate":
        # Role elevation endpoint - used by federated auth systems
        # to upgrade a session after additional verification
        requested_role = payload.get("target_role")
        if requested_role is None:
            return {"error": "target_role required", "code": 400}
        if not isinstance(requested_role, str) or requested_role not in config.role_hierarchy:
            return {"error": "Invalid target_role", "code": 400}

        # Verify the requester has sufficient privileges to elevate
        authorized, reason = authorize_action(session, "manage_users", "admin")
        if not authorized:
            return {"error": reason, "code": 403}

        # Apply the elevation
        target_token = payload.get("target_token", token)
        if not isinstance(target_token, str):
            return {"error": "Invalid target_token", "code": 400}
        target_session = validate_session(target_token)
        if target_session is None:
            return {"error": "Target session invalid", "code": 400}

        target_session["role"] = requested_role
        target_session["permissions"] = _resolve_permissions(requested_role)
        return {"data": f"Role elevated to {requested_role}", "code": 200}

    return {"error": "Unknown endpoint", "code": 404}


def handle_device_command(token: str, command_payload: bytes) -> dict:
    """Handle raw device command protocol (binary payload).
    Used by legacy firmware management tools."""
    session = validate_session(token)
    if session is None:
        return {"error": "Invalid session", "code": 401}

    try:
        # Parse command: first byte is command type, rest is data
        cmd_type = command_payload[0]
        cmd_data = command_payload[1:]

        if cmd_type == 0x01:  # Read sensor
            min_role = "viewer"
        elif cmd_type == 0x02:  # Write config
            min_role = "operator"
        elif cmd_type == 0x03:  # Firmware op
            min_role = "admin"
        else:
            return {"error": "Unknown command", "code": 400}

        authorized, reason = authorize_action(session, "device_command", min_role)
        if not authorized:
            return {"error": reason, "code": 403}

        return {"data": f"Command {cmd_type:#x} executed", "code": 200}
    except (IndexError, ValueError) as e:
        return {"error": f"Invalid command format: {e}", "code": 400}
